{
  "scope_issues": [
    "The policy allows Gift Aid on donations from individuals, but does not specify whether it applies to multiple donations or only one; the decision target is per donation."
  ],
  "statuses": [
    {
      "evidence_quote": "You must be recognised as a charity or CASC for tax purposes.",
      "id": "a1",
      "justification": "The customer scenario states that the charity's HMRC recognition was confirmed as still in force on 16 March 2026, which supports the proposition that the charity is recognised for tax purposes.",
      "status": "TRUE"
    },
    {
      "evidence_quote": "The donor must have paid at least as much in Income Tax or Capital Gains Tax in that tax year as you want to claim in Gift Aid",
      "id": "a2",
      "justification": "Elaine Carter's Income Tax paid for 2025–26 was £980, and the total Gift Aid claimed for her donations that year is £80. Since £80 is less than £980, the donor has paid at least as much in tax as the claimed Gift Aid, supporting the proposition.",
      "status": "TRUE"
    },
    {
      "evidence_quote": "You must make a Gift Aid declaration that gives you permission to claim it",
      "id": "a3",
      "justification": "The customer scenario explicitly states that Elaine Carter's signed Gift Aid declaration covers this payment, confirming the proposition is true.",
      "status": "TRUE"
    },
    {
      "evidence_quote": "You cannot claim on donations: made through Payroll Giving",
      "id": "a4",
      "justification": "The donation was made via direct bank transfer, not through Payroll Giving, so the proposition that the donation is not made through Payroll Giving is supported.",
      "status": "TRUE"
    },
    {
      "evidence_quote": "You cannot claim on donations: that are a payment for goods or services or made because your charity bought goods and services",
      "id": "a5",
      "justification": "The fundraiser checked the records and confirms Elaine received no goods, services or benefit in exchange, so the donation is not for goods or services, supporting the proposition.",
      "status": "TRUE"
    },
    {
      "evidence_quote": "You cannot claim on donations: where the donor gets a ‘benefit’ over a certain limit",
      "id": "a6",
      "justification": "There is no mention of any benefit to Elaine or any benefit over a limit; the scenario states the donation was for an emergency veterinary appeal and no benefit was provided, so the proposition holds.",
      "status": "TRUE"
    },
    {
      "evidence_quote": "You cannot claim on donations: of shares",
      "id": "a7",
      "justification": "The donation was a bank transfer for an emergency appeal, not shares, so the proposition that it is not shares is true.",
      "status": "TRUE"
    },
    {
      "evidence_quote": "You cannot claim on donations: from charity cards or of vouchers, for example Charities Aid Foundation (CAF) vouchers",
      "id": "a8",
      "justification": "The processor's CAF charity-card and voucher receipts are stated to be different payments with different settlement references; FP-0316-EL was Elaine's direct bank transfer, so this donation is not from a charity card or voucher, supporting the proposition.",
      "status": "TRUE"
    }
  ]
}
